import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const currentDir = path.dirname(fileURLToPath(import.meta.url));
const templatesDir = path.resolve(currentDir, "../templates");

const projectRoot = process.env.INIT_CWD || process.cwd();

const testTemplateDir = path.join(templatesDir, "test");
const testTargetDir = path.join(projectRoot, "test");

const workflowTemplateDir = path.join(
  templatesDir,
  ".github",
  "workflows"
);

const workflowTargetDir = path.join(
  projectRoot,
  ".github",
  "workflows"
);

function copyDirectory(source, target) {
  if (!fs.existsSync(source)) {
    throw new Error(`Templates directory not found: ${source}`);
  }

  fs.mkdirSync(target, { recursive: true });

  for (const entry of fs.readdirSync(source, { withFileTypes: true })) {
    const src = path.join(source, entry.name);
    const dest = path.join(target, entry.name);

    if (entry.isDirectory()) {
      copyDirectory(src, dest);
    } else if (entry.isFile() && !fs.existsSync(dest)) {
      fs.copyFileSync(src, dest);
      console.log(`Copied: ${path.relative(projectRoot, dest)}`);
    }
  }
}

function configurePackageJson() {
  const packageJsonPath = path.join(projectRoot, "package.json");

  if (!fs.existsSync(packageJsonPath)) {
    throw new Error("No package.json found in the target project.");
  }

  const packageJson = JSON.parse(
    fs.readFileSync(packageJsonPath, "utf8")
  );

  packageJson.scripts ??= {};
  packageJson.devDependencies ??= {};

  // Preserve existing scripts.
  packageJson.scripts.test ??= "jest --runInBand";
  packageJson.scripts.build ??=
    "node --check src/server.js && node --check src/app.js";

  // Preserve existing dependency versions.
  packageJson.devDependencies.jest ??= "^30.0.0";
  packageJson.devDependencies.supertest ??= "^7.0.0";

  fs.writeFileSync(
    packageJsonPath,
    JSON.stringify(packageJson, null, 2) + "\n"
  );

  console.log("VibeShield: package.json configured.");
}

try {
  // Copy test templates.
  copyDirectory(testTemplateDir, testTargetDir);
  console.log("VibeShield: test files copied successfully.");

  // Copy GitHub Actions workflow.
  if (fs.existsSync(workflowTemplateDir)) {
    copyDirectory(workflowTemplateDir, workflowTargetDir);
    console.log("VibeShield: CI workflow copied successfully.");
  } else {
    console.warn(
      "VibeShield: CI workflow template not found; skipping workflow installation."
    );
  }

  // Configure scripts and dependencies.
  configurePackageJson();

  console.log(
    "VibeShield setup completed. Run npm install to install dependencies."
  );
} catch (error) {
  console.error("VibeShield installation failed:", error.message);
  process.exitCode = 1;
}